CREATE TABLE t_p23442598_alumni_network_app.groups (id SERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, type VARCHAR(20) NOT NULL DEFAULT 'group', description TEXT NOT NULL DEFAULT '', initials VARCHAR(4) NOT NULL, color VARCHAR(80) NOT NULL DEFAULT 'from-violet-500 to-purple-700', members_count INT NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'active', created_at TIMESTAMP NOT NULL DEFAULT NOW())
